      "headings": [{"level": "running_header", "text": "HEIDEGGER EN FRANCE", "position": "top"}],
      "paragraph_starts": [
        {"text": "partie à ferrailler contre son ancien ami, Jean-François Courtine, à propos de", "continues_from_previous": true, "continues_to_next": false},
        {"text": "Dès lors, comment traduire les deux mots qui dénotent cette distinction?", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Cette querelle d'apparence byzantine recèle l'enjeu suivant : faut-il opter pour", "continues_from_previous": false, "continues_to_next": false}
      ],
      "body_note_refs": [{"marker": "10", "context": "Heidegger veut montrer"}, {"marker": "11", "context": "lancé la polémique"}],
      "footnotes": [
        {"marker": "10", "text_start": "Voir en particulier Être et temps, § 15-18, 22."},
        {"marker": "11", "text_start": "Dans son avertissement à la traduction française de HEIDEGGER, Les Problèmes fondamentaux de la phénoménologie, Paris, Gallimard, 1985,"}
